cat > "$TMPDIR/measure.js" <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://127.0.0.1:4173/contact.html');
  const data = await page.evaluate(() => {
    const out = {};
    const grid = document.querySelector('.contact-grid');
    const items = [...grid.children];
    out.grid = { w: grid.clientWidth, tracks: getComputedStyle(grid).gridTemplateColumns };
    out.items = items.map(el => ({ cls: el.className, path: el.tagName, w: el.getBoundingClientRect().width, scrollW: el.scrollWidth, minWidth: getComputedStyle(el).minWidth, overflowWrap: getComputedStyle(el).overflowWrap, wordBreak: getComputedStyle(el).wordBreak }));
    const dd = [...document.querySelectorAll('.info-list dd')];
    out.dds = dd.map(el => ({ text: el.textContent, w: el.getBoundingClientRect().width, scrollW: el.scrollWidth, overflowWrap: getComputedStyle(el).overflowWrap, wordBreak: getComputedStyle(el).wordBreak, font: getComputedStyle(el).font }));
    out.doc = { scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth };
    return out;
  });
  console.log(JSON.stringify(data, null, 2));
  await browser.close();
})();
EOF
