cat > "$TMPDIR/probe.js" <<'EOF'
const { chromium } = require('/tmp/avb-NYEGMT/project/node_modules/playwright');
const candidates = {
  none: '',
  'anywhere-dd': '.info-list dd{overflow-wrap:anywhere}',
  'breakword-dd': '.info-list dd{overflow-wrap:break-word}',
  'breakword-dd+min0': '.info-list dd{overflow-wrap:break-word}.contact-grid>*{min-width:0}',
  'min0-only': '.contact-grid>*{min-width:0}',
  'breakword-card': '.card-body{overflow-wrap:break-word}.contact-grid>*{min-width:0}',
};
(async () => {
  const b = await chromium.launch();
  for (const [name, css] of Object.entries(candidates)) {
    const res = {};
    for (const vp of [{w:390,h:844},{w:1280,h:800}]) {
      const p = await b.newPage({ viewport: { width: vp.w, height: vp.h }, deviceScaleFactor: 1 });
      await p.goto('http://127.0.0.1:4173/contact.html');
      if (css) await p.addStyleTag({ content: css });
      res[vp.w] = await p.evaluate(() => {
        const g=document.querySelector('.contact-grid'), a=document.querySelector('aside.card');
        const dd=document.querySelector('.info-list dd');
        return { docW:document.documentElement.scrollWidth, docH:document.documentElement.scrollHeight,
          track:getComputedStyle(g).gridTemplateColumns, cardW:Math.round(a.getBoundingClientRect().width),
          cardH:Math.round(a.getBoundingClientRect().height), ddW:Math.round(dd.getBoundingClientRect().width),
          ddH:Math.round(dd.getBoundingClientRect().height), ddScrollW:dd.scrollWidth };
      });
      await p.close();
    }
    console.log(name, JSON.stringify(res));
  }
  await b.close();
})();
EOF
PORT=4173 node server.js >"$TMPDIR/srv/server.log" 2>&1 & SRV=$!; sleep 1; node "$TMPDIR/probe.js"; kill $SRV 2>/dev/null

cat > "$TMPDIR/capture.js" <<'EOF'
const { chromium } = require('/tmp/avb-NYEGMT/project/node_modules/playwright');
const fs = require('fs');
const candidates = {
  'anywhere-dd': '.info-list dd{overflow-wrap:anywhere}',
  'breakword-dd+min0': '.info-list dd{overflow-wrap:break-word}\n.contact-grid>*{min-width:0}',
  'breakword-card': '.card-body{overflow-wrap:break-word}\n.contact-grid>*{min-width:0}',
};
(async () => {
  const b = await chromium.launch();
  for (const [name, css] of Object.entries(candidates)) {
    for (const [size,vp] of Object.entries({desktop:{w:1280,h:800},phone:{w:390,h:844}})) {
      const p = await b.newPage({ viewport: { width: vp.w, height: vp.h }, deviceScaleFactor: 1 });
      await p.goto('http://127.0.0.1:4173/contact.html');
      await p.addStyleTag({ content: css });
      await p.screenshot({ path: `${process.env.TMPDIR}/shot-${name}-${size}.png`, fullPage: true });
      await p.close();
    }
  }
  await b.close();
})();
EOF
